# -*- coding: utf-8 -*-
"""Tiny local HTTP wrapper around ntu_attend.py, for triggering from a phone
Shortcut over Tailscale (NOT exposed to the public internet -- only reachable
from devices on your own Tailscale network).

Every request must include: Authorization: Bearer <token>
Run setup_api_token.py once to generate that token.

Usage:
    .venv\\Scripts\\python.exe local_api.py
"""
import logging

import keyring
from flask import Flask, jsonify, request

import ntu_attend

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
logger = logging.getLogger("ntu-mattend-api")

SERVICE = "ntu-mattend-api"
PORT = 8765

app = Flask(__name__)
_token = keyring.get_password(SERVICE, "token")
if not _token:
    raise SystemExit("找不到 API token，請先執行 setup_api_token.py。")


@app.before_request
def check_auth():
    auth = request.headers.get("Authorization", "")
    if auth != f"Bearer {_token}":
        logger.warning("rejected request from %s: bad/missing token", request.remote_addr)
        return jsonify({"error": "unauthorized"}), 401


@app.route("/status", methods=["GET"])
def status():
    try:
        return jsonify(ntu_attend.get_status())
    except Exception as e:
        logger.exception("status failed")
        return jsonify({"error": str(e)}), 500


@app.route("/sign-in", methods=["POST"])
def sign_in():
    logger.info("sign-in requested from %s", request.remote_addr)
    try:
        return jsonify(ntu_attend.sign_in())
    except Exception as e:
        logger.exception("sign-in failed")
        return jsonify({"error": str(e)}), 500


@app.route("/sign-out", methods=["POST"])
def sign_out():
    logger.info("sign-out requested from %s", request.remote_addr)
    try:
        return jsonify(ntu_attend.sign_out())
    except Exception as e:
        logger.exception("sign-out failed")
        return jsonify({"error": str(e)}), 500


if __name__ == "__main__":
    logger.info("starting on 0.0.0.0:%s (Tailscale-only intended reach)", PORT)
    app.run(host="0.0.0.0", port=PORT)

"""MCP server for NTU's staff attendance sign-in/out system (my.ntu.edu.tw/mattend)."""
from mcp.server import MCPServer

import ntu_attend

mcp = MCPServer("ntu-mattend")


@mcp.tool()
def attendance_status() -> dict:
    """Read today's sign-in/sign-out time and recent daily records. Read-only, no side effects."""
    return ntu_attend.get_status()


@mcp.tool()
def sign_in() -> dict:
    """Click 簽到 (clock in) on NTU's attendance system.

    This performs a REAL action that permanently records today's clock-in time
    in an official NTU HR system -- it is not a simulation. Only call this when
    the user has explicitly asked to sign in / 簽到 right now, in this
    conversation turn. Never call it speculatively, proactively, or on a
    schedule. The system itself enforces that this only works from an on-campus
    wired office network IP; requests from elsewhere are rejected by the server.
    """
    return ntu_attend.sign_in()


@mcp.tool()
def sign_out() -> dict:
    """Click 簽退 (clock out, can be done multiple times) on NTU's attendance system.

    This performs a REAL action recorded in an official NTU HR system -- it is
    not a simulation. Only call this when the user has explicitly asked to sign
    out / 簽退 right now, in this conversation turn. Never call it speculatively,
    proactively, or on a schedule.
    """
    return ntu_attend.sign_out()


if __name__ == "__main__":
    mcp.run()
